def floor_div(a, b):
    return a // b


def offset_at(t, points):
    """points: sorted list of (t, offset)."""
    if not points:
        return 0
    if t <= points[0][0]:
        return points[0][1]
    if t >= points[-1][0]:
        return points[-1][1]
    lo, hi = 0, len(points) - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if points[mid][0] <= t:
            lo = mid
        else:
            hi = mid
    t1, o1 = points[lo]
    t2, o2 = points[hi]
    if t == t1:
        return o1
    return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)


def fmt_hour(end):
    return datetime.fromtimestamp(end, tz=timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")


def rnd(x):
    r = round(x, 2)
    return r + 0.0 if r != 0 else 0.0


def build_station(sid, interval, rows, syncs):
    # rows: dict logger_utc -> (upload, row); syncs: dict logger_utc -> (upload, ref_offset)
    points = sorted((t, o) for t, (u, o) in syncs.items())
    kept = []
    for t in sorted(rows):
        row = rows[t][1]
        kept.append((t + offset_at(t, points), t, row))
    kept.sort(key=lambda x: (x[0], x[1]))
    hour_of = lambda c: -((-c) // 3600) * 3600
    first = hour_of(kept[0][0])
    last = hour_of(kept[-1][0])
    expected = 3600 // interval if interval else 0
    nh = (last - first) // 3600 + 1
    acc = [{q: {"vals": [], "n": 0} for q in QUANTITIES} for _ in range(nh)]
    vec = [[0.0, 0.0, 0] for _ in range(nh)]
    rain = [0.0] * nh
    prev_rain = None
    for c, _, row in kept:
        idx = (hour_of(c) - first) // 3600
        for q in QUANTITIES:
            v = row.get(q)
            if v is None:
                continue
            a = acc[idx][q]
            a["n"] += 1
            if q in ("temp", "rh", "pres", "wspd"):
                a["vals"].append(v)
        wd = row.get("wdir")
        ws = row.get("wspd")
        if wd is not None and ws is not None and ws > 0:
            rad = math.radians(wd)
            vec[idx][0] += math.sin(rad)
            vec[idx][1] += math.cos(rad)
            vec[idx][2] += 1
        r = row.get("rain")
        if r is not None:
            if prev_rain is not None and (c - prev_rain[0]) * 2 <= 5 * interval:
                rain[idx] += (r - prev_rain[1]) if r >= prev_rain[1] else r
            prev_rain = (c, r)

    def enough(n):
        return n * 4 >= expected * 3

    hours = []
    for i in range(nh):
        entry = {"hour": fmt_hour(first + 3600 * (i + 1) - 3600 + 0) if False else fmt_hour(first + 3600 * i)}
        for q in QUANTITIES:
            a = acc[i][q]
            n = a["n"]
            value = None
            if enough(n):
                if q in ("temp", "rh", "pres", "wspd"):
                    value = rnd(math.fsum(a["vals"]) / n)
                elif q == "wdir":
                    sx, sy, cnt = vec[i]
                    if cnt > 0:
                        ang = math.degrees(math.atan2(sx, sy)) % 360.0
                        value = rnd(ang)
                        if value >= 360:
                            value = 0.0
                elif q == "rain":
                    value = rnd(rain[i])
            entry[q] = {"value": value, "n": n}
        hours.append(entry)
    return {"station": sid, "interval_s": interval, "hours": hours}


def main(argv):
    indir, outfile = argv[1], argv[2]
    names = sorted(n for n in os.listdir(indir)
                   if n.endswith(".log") and os.path.isfile(os.path.join(indir, n)))
    stations = {}
    for name in names:
        info, rows, syncs = read_dump(os.path.join(indir, name))
        sid = info["station"]
        if sid is None:
            continue
        st = stations.setdefault(sid, {"interval": None, "up": -1, "rows": {}, "syncs": {}, "nrows": 0})
        up = info["upload"] if info["upload"] is not None else 0
        if info["interval"] is not None and up >= st["up"]:
            st["interval"] = info["interval"]
            st["up"] = up
        for t, row in rows:
            cur = st["rows"].get(t)
            if cur is None or up > cur[0]:
                st["rows"][t] = (up, row)
        for t, off in syncs:
            cur = st["syncs"].get(t)
            if cur is None or up >= cur[0]:
                st["syncs"][t] = (up, off)
    out = {"stations": []}
    for sid in sorted(stations):
        st = stations[sid]
        if not st["rows"]:
            continue
        out["stations"].append(build_station(sid, st["interval"], st["rows"], st["syncs"]))
    with open(outfile, "w", encoding="utf-8") as fh:
        json.dump(out, fh)


if __name__ == "__main__":
    main(sys.argv)
